import { concatBytes } from "../bytes.mjs";
import { sha1 } from "./sha1.mjs";

const BLOCK_SIZE = 64;

function normalizeKey(key) {
  if (key.length > BLOCK_SIZE) {
    return sha1(key);
  }

  const normalized = new Uint8Array(BLOCK_SIZE);
  normalized.set(key, 0);
  return normalized;
}

export function hmacSha1(key, message) {
  const normalizedKey = normalizeKey(key);
  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerPad[index] = normalizedKey[index] ^ 0x36;
    outerPad[index] = normalizedKey[index] ^ 0x5c;
  }

  const innerHash = sha1(concatBytes(innerPad, message));
